(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  let wy = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  wx += Math.sin((x + y) * 0.01 + t * 0.15) * 8;
  wy += Math.cos((x - y) * 0.012 - t * 0.18) * 8;
  const sx = x + wx, sy = y + wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+1.5)*110, 40+Math.cos(t*0.65+2.5)*65, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.38+3.2)*95, 210+Math.sin(t*0.58+0.8)*75, 0.075, 1.8, 1.05]
  ];
  let aS = 0, iS = 0, tS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    tS += Math.sin(d*f*1.4 - t*sp*0.4 + 3.0) * w * 0.5;
  }
  const n = src.length, act = aS/n, inh = iS/n, ter = tS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*0.6)*Math.sin(sy*0.07-t*0.5)*0.3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.2)*0.2;
  const c2x = 160+Math.sin(t*0.25)*60, c2y = 100+Math.cos(t*0.3)*40;
  const d2 = Math.sqrt((sx-c2x)**2 + (sy-c2y)**2), a2 = Math.atan2(sy-c2y, sx-c2x);
  const spiral2 = Math.sin(d2*0.06-a2*2.5-t*1.8)*0.25;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.15;
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((ter*0.6 + inh*0.5 - act*0.3 + spiral2)*1.8);
  const reaction = r1*0.7 + r2*0.3;
  const blend = reaction*0.65 + cell*0.2 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,45,95],[18,90,120],[25,140,135],[45,175,140],[140,195,120],[210,185,80],[220,140,65],[195,85,60],[150,45,55],[85,22,48],[30,15,42],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge = Math.abs(reaction)>0.7?1.12:Math.abs(reaction)>0.5?1.05:1.0;
  const breathe = 1.0+Math.sin(t*0.4)*0.04;
  const L = lum*edge*breathe;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*L)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*L)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*L)|0
  ];
}
